<script>
document.addEventListener('DOMContentLoaded',function(){const search=document.getElementById('news-search'),cat=document.getElementById('news-category'),btn=document.getElementById('news-filter'),cards=[...document.querySelectorAll('.news-card')],empty=document.getElementById('empty-news'),count=document.getElementById('news-count');function filter(){const q=(search.value||'').trim().toLowerCase(),c=cat.value;let n=0;cards.forEach(x=>{const okQ=!q||x.dataset.search.toLowerCase().includes(q),okC=c==='all'||x.dataset.category===c,ok=okQ&&okC;x.style.display=ok?'flex':'none';if(ok)n++});empty.style.display=n?'none':'block';count.textContent=n+' مطلب'}btn.addEventListener('click',filter);search.addEventListener('input',filter);cat.addEventListener('change',filter)});
</script>
